function i(){return fetch("https://education.ufl.edu/news/wp-json/wp/v2/posts?categories=1518&per_page=3&_embed").then(e=>{if(!e.ok)throw new Error(`HTTP error! Status: ${e.status}`);return e.json()}).then(e=>(s(e),console.log("Posts retrieved:",e),e)).catch(e=>{console.error("Error fetching posts:",e)})}function s(t){for(let e=0;e<t.length;e++){const r=t[e];let l=r.title.rendered,n=r.link,o=r._embedded["wp:featuredmedia"][0];if(o){let a=o.link,c=o.alt_text;console.log(l,n,a)}else console.log("featuredImage not available.")}}i();
